const std = @import("std");

fn build(arr: []i32, tree: []i32, node: usize, left: usize, right: usize) void {
    if (left == right) {
        tree[node] = arr[left];
        return;
    }
    const mid = (left + right) / 2;
    build(arr, tree, 2 * node + 1, left, mid);
    build(arr, tree, 2 * node + 2, mid + 1, right);
    tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
}

fn query(tree: []i32, node: usize, left: usize, right: usize, ql: usize, qr: usize) i32 {
    if (ql > right or qr < left) return 0;
    if (ql <= left and right <= qr) return tree[node];
    const mid = (left + right) / 2;
    return query(tree, 2 * node + 1, left, mid, ql, qr) +
           query(tree, 2 * node + 2, mid + 1, right, ql, qr);
}

pub fn main() !void {
    const arr = [_]i32{ 1, 3, 5, 7, 9, 11 };
    var tree: [24]i32 = undefined;
    build(arr, tree, 0, 0, arr.len - 1);

    std.debug.print("Sum 0-3: {}\n", .{query(tree, 0, 0, arr.len - 1, 0, 3)});
    std.debug.print("Sum 2-5: {}\n", .{query(tree, 0, 0, arr.len - 1, 2, 5)});
}

